import java.util.*;
public final class UnitConverter {
 private static final Map<String,Map<String,Double>> FACTORS=new LinkedHashMap<>();static{put("length",new String[]{"mm","cm","m","km","in","ft","yd","mi"},new double[]{.001,.01,1,1000,.0254,.3048,.9144,1609.344});put("weight",new String[]{"mg","g","kg","tonne","lb","oz"},new double[]{.000001,.001,1,1000,.45359237,.028349523125});put("speed",new String[]{"m/s","km/h","mph"},new double[]{1,1/3.6,0.44704});put("data size",new String[]{"B","KB","MB","GB","KiB","MiB","GiB"},new double[]{1,1000,1e6,1e9,1024,1048576,1073741824});put("time",new String[]{"ms","s","min","h","day"},new double[]{.001,1,60,3600,86400});}
 private static void put(String cat,String[]units,double[]f){Map<String,Double>m=new LinkedHashMap<>();for(int i=0;i<units.length;i++)m.put(units[i],f[i]);FACTORS.put(cat,m);}
 public static Map<String,Object> units(){Map<String,Object>all=new LinkedHashMap<>(FACTORS);all.put("temperature",Arrays.asList("C","F","K"));return all;}
 public static double convert(double value,String category,String from,String to){if(category.equalsIgnoreCase("temperature")){double c;if(from.equals("C"))c=value;else if(from.equals("F"))c=(value-32)*5/9;else if(from.equals("K"))c=value-273.15;else throw new IllegalArgumentException("Choose C, F, or K.");double out;if(to.equals("C"))out=c;else if(to.equals("F"))out=c*9/5+32;else if(to.equals("K"))out=c+273.15;else throw new IllegalArgumentException("Choose C, F, or K.");return out;}Map<String,Double>m=FACTORS.get(category.toLowerCase(Locale.ROOT));if(m==null)throw new IllegalArgumentException("Choose a supported unit category.");Double a=m.get(from),b=m.get(to);if(a==null||b==null)throw new IllegalArgumentException("Choose units from the selected category.");return value*a/b;}
 public static void main(String[]args){try{double v=Double.parseDouble(args.length>0?args[0]:"1");System.out.println(convert(v,"length","km","mi"));}catch(Exception e){System.err.println(e.getMessage());}}
}

